A={}; Q={}; EXTRA={}
def safe(s):
 return re.sub(r'<(?!/?(?:p|div|strong|em|b|i|sub|sup|ol|ul|li|span|br|a|table|thead|tbody|tr|td|th|figure|svg|path|g|rect|text|polyline|circle|figcaption|h[1-6])(?:[\s/>]))', '&lt;', str(s))
def p(s):return '<p>'+safe(s)+'</p>'
def ol(*xs):return '<ol type="a">'+''.join('<li>'+safe(x)+'</li>' for x in xs)+'</ol>'
def answer(label,s):A[label]=safe(s) if s.startswith('<') else p(s)
def prompt(label,s):Q[label]=safe(s) if s.startswith('<') else p(s)
def table(headers,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join('<th>'+str(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def stem(data,scale=1):
 d=defaultdict(list)
 for x in sorted(data):v=round(x*scale);d[v//10].append(v%10)
 return table(['Stem','Leaves'],[(k,' '.join(map(str,d[k]))) for k in range(min(d),max(d)+1)])+p('Key: '+('1 | 2 = 1.2' if scale==10 else '3 | 2 = 32')+'. Repeated leaves represent repeated observations.')
def chart(title,labels,series,kind='bar',ylabel='Frequency'):
 # Simple local SVG, all marks inherit currentColor for answer concealment.
 W=780;H=350;left=70;right=30;top=45;bottom=75;n=len(labels);plotw=W-left-right;ploth=H-top-bottom
 vals=[v for name,ys in series for v in ys];mx=max(vals)*1.15 or 1
 svg=f'<svg viewBox="0 0 {W} {H}" role="img" aria-label="{escape(title)}"><title>{escape(title)}</title>'
 svg+='<g fill="none" stroke="currentColor" stroke-width="2"><path d="M70,45 V275 H750"/></g><g fill="currentColor" font-family="Arial,sans-serif" font-size="16">'
 for k in range(6):
  val=mx*k/5;y=top+ploth*(1-val/mx);svg+=f'<text x="60" y="{y+5}" text-anchor="end">{val:.3g}</text>'
 for j,label in enumerate(labels):
  x=left+plotw*(j+.5)/n;svg+=f'<text x="{x}" y="300" text-anchor="middle">{escape(str(label))}</text>'
 svg+=f'<text x="70" y="25">{escape(ylabel)}</text></g>'
 for si,(name,ys) in enumerate(series):
  pts=[]
  for j,v in enumerate(ys):
   x=left+plotw*(j+.5)/n;y=top+ploth*(1-v/mx);pts.append(f'{x},{y}')
   if kind=='bar':
    bw=plotw/n*.72/len(series);xx=x-plotw/n*.36+si*bw
    svg+=f'<rect x="{xx}" y="{y}" width="{bw}" height="{top+ploth-y}" fill="currentColor" opacity="{1-si*.3}"/>'
   elif kind=='line':svg+=f'<path d="M{x},275 V{y}" stroke="currentColor"/><circle cx="{x}" cy="{y}" r="4" fill="currentColor"/>'
   else:svg+=f'<circle cx="{x}" cy="{y}" r="4" fill="currentColor"/>'
  if kind not in ['bar','line']:svg+='<polyline points="'+' '.join(pts)+f'" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="{"7 4" if si else "none"}"/>'
 svg+='</svg>'
 return '<figure>'+svg+'<figcaption>'+escape(title)+('. Solid: '+escape(series[0][0])+'; dashed: '+escape(series[1][0])+'.' if len(series)==2 else '')+'</figcaption></figure>'
def boxplot(vals,label='Box plot'):
 lo,q1,med,q3,hi=vals;span=hi-lo or 1
 def x(v):return 70+640*(v-lo)/span
 svg=f'<svg viewBox="0 0 780 180" role="img" aria-label="{escape(label)}: {escape(str(vals))}"><g stroke="currentColor" fill="none" stroke-width="2"><path d="M{x(lo)},70 H{x(hi)}"/><rect x="{x(q1)}" y="40" width="{x(q3)-x(q1)}" height="60"/>'
 for v in [lo,med,hi]:svg+=f'<path d="M{x(v)},40 V100"/>'
 svg+='</g><g fill="currentColor" font-size="18" text-anchor="middle">'
 for j,v in enumerate(vals):svg+=f'<text x="{x(v)}" y="{130+22*(j%2)}">{v:g}</text>'
 return '<figure>'+svg+'</g></svg><figcaption>'+label+'</figcaption></figure>'
def five(data):
 a=sorted(data);n=len(a);return [a[0],median(a[:n//2]),median(a),median(a[(n+1)//2:]),a[-1]]
def prob(v):return f'{v:.4f}' if v>=.00005 else f'{v:.3g}'
def ci(mu,sigma,n,level,student=False):
 crit=t.ppf((1+level)/2,n-1) if student else norm.ppf((1+level)/2)
 se=sigma/sqrt(n);e=crit*se
 return p(f'{"t" if student else "z"}* = {crit:.4f}'+(f' with df = {n-1}' if student else '')+f'. Standard error = {sigma:g}/√{n} = {se:.4f}. Margin = {crit:.4f} × {se:.4f} = {e:.4f}.')+p(f'Interval = {mu:.4f} ± {e:.4f} = <strong>({mu-e:.4f}, {mu+e:.4f})</strong>. We estimate the population mean with {100*level:g}% confidence. In repeated random samples, this method captures the fixed population mean about {100*level:g}% of the time.')
def pci(x,n,level,plus=False):
 xx=x+2 if plus else x;nn=n+4 if plus else n;phat=xx/nn;z=norm.ppf((1+level)/2);se=sqrt(phat*(1-phat)/nn);e=z*se
 return p((f'Add two successes and two failures: adjusted count = {xx}, adjusted n = {nn}. ' if plus else '')+f'p̂ = {xx}/{nn} = {phat:.5f}; z* = {z:.4f}; SE = √[p̂(1 − p̂)/{nn}] = {se:.5f}.')+p(f'Interval = {phat:.5f} ± {e:.5f} = <strong>({phat-e:.5f}, {phat+e:.5f})</strong>, or about {100*(phat-e):.2f}% to {100*(phat+e):.2f}%. Interpret this as a {100*level:g}% confidence estimate for the population proportion, assuming the sampling conditions hold.')
