def uniform_graph(a,b,l,h):
 def x(v):return 70+640*(v-a)/(b-a)
 return f'<figure><svg viewBox="0 0 780 240" role="img" aria-label="Uniform density on [{a},{b}]"><path d="M70 30 V190 H730" fill="none" stroke="currentColor"/><rect x="{x(l)}" y="60" width="{x(h)-x(l)}" height="130" fill="currentColor" opacity=".15"/><path d="M70 60 H710" stroke="currentColor" stroke-width="3"/><g fill="currentColor" font-size="18"><text x="5" y="65">{1/(b-a):g}</text>'+''.join(f'<text x="{x(v)}" y="220" text-anchor="middle">{v:g}</text>' for v in sorted(set([a,l,h,b])))+'</g></svg></figure>'+p(f'The horizontal density has height 1/({b}−{a}), zero outside [{a},{b}]. The shaded rectangle runs from {l} to {h}.')

